const input = $json || {};
const chatId = input.chatId;
const callbackQueryId = input.callbackQueryId || null;
const msg = String(input.msg || "").trim();

let savedSession = input.session || input.json?.session || input.data?.session || null;
if (typeof savedSession === "string") {
  try { savedSession = JSON.parse(savedSession); } catch { savedSession = null; }
}

