function response(chatId, text, replyMarkup, session, callbackQueryId = null) {
  return [{ json: { chatId, text, replyMarkup, session, callbackQueryId } }];
}
function responseWithAI(chatId, aiPrompt, replyMarkup, session, callbackQueryId = null) {
  return [{ json: { chatId, useAI: true, aiPrompt, replyMarkup, session, callbackQueryId } }];
}
function norm(v) {
  return String(v || "").toLowerCase().trim().replace(/[^a-z0-9\s-]/g, " ").replace(/\s+/g, " ");
}
function productText(p) {
  return [p.name, p.category, p.shortDescription, ...(p.skinTypes||[]), ...(p.concerns||[]), ...(p.benefits||[]), p.usage, p.notSuitableFor].join(" ");
}
function productBlock(p) {
  return `
Name: ${p.name}
Category: ${p.category}
Price: ${p.price}
Stock: ${p.stock}
Suitable for: ${p.skinTypes.join(", ")}
Helps with: ${p.concerns.join(", ")}
Description: ${p.shortDescription}
Benefits: ${p.benefits.join(", ")}
Usage: ${p.usage}
Not suitable for: ${p.notSuitableFor}
Product URL: ${p.buyLink}
`;
}
function findProductById(id) { return PRODUCTS.find(p => p.id === id); }
function orderCode() { return `SKN-${Math.floor(1000 + Math.random() * 9000)}`; }

function mainMenu() {
  return { inline_keyboard: [
    [{ text: "🧴 Product consultation", callback_data: "consulting" }],
    [{ text: "📦 Track order", callback_data: "track_order" }, { text: "🛒 Create test order", callback_data: "start_order" }],
    [{ text: "ℹ️ About this demo", callback_data: "about_demo" }]
  ]};
}
function consultingMenu() {
  return { inline_keyboard: [
    [{ text: "🔍 Ask about a product", callback_data: "product_info" }],
    [{ text: "💆 Recommendations by skin type", callback_data: "skin_type_advice" }],
    [{ text: "🩺 Recommendations by concern", callback_data: "skin_problem_advice" }],
    [{ text: "🔙 Main menu", callback_data: "back_to_main" }]
  ]};
}
function skinTypesMenu() {
  return { inline_keyboard: [
    [{ text: "Oily", callback_data: "skin_oily" }, { text: "Dry", callback_data: "skin_dry" }],
    [{ text: "Combination", callback_data: "skin_combination" }, { text: "Sensitive", callback_data: "skin_sensitive" }],
    [{ text: "I don't know my skin type", callback_data: "skin_unknown" }],
    [{ text: "🔙 Back", callback_data: "consulting" }]
  ]};
}
function problemsMenu() {
  return { inline_keyboard: [
    [{ text: "Acne / breakouts", callback_data: "problem_acne" }, { text: "Dark spots", callback_data: "problem_spot" }],
    [{ text: "Dryness", callback_data: "problem_dryness" }, { text: "Excess oil", callback_data: "problem_oiliness" }],
    [{ text: "Redness / sensitivity", callback_data: "problem_sensitive" }, { text: "Fine lines", callback_data: "problem_lines" }],
    [{ text: "🔙 Back", callback_data: "consulting" }]
  ]};
}
function backMenu() {
  return { inline_keyboard: [
    [{ text: "🔙 Back to consultation", callback_data: "consulting" }],
    [{ text: "🏠 Main menu", callback_data: "back_to_main" }]
  ]};
}
function productActions(id) {
  return { inline_keyboard: [
    [{ text: "🛒 Order this product", callback_data: `order_${id}` }],
    [{ text: "💬 Ask about this product", callback_data: `ask_${id}` }],
    [{ text: "🔙 Back", callback_data: "consulting" }]
  ]};
}
function orderBack() {
  return { inline_keyboard: [[{ text: "Cancel and return to main menu", callback_data: "back_to_main" }]] };
}
function orderConfirm() {
  return { inline_keyboard: [
    [{ text: "✅ Confirm order", callback_data: "confirm_order" }],
    [{ text: "✏️ Edit details", callback_data: "edit_order" }],
    [{ text: "❌ Cancel order", callback_data: "cancel_order" }]
  ]};
}

function scoreProduct(p, q) {
  const query = norm(q);
  const text = norm(productText(p));
  let score = 0;
  const aliases = {
    "sunscreen": ["spf", "sun protection"],
    "moisturizer": ["hydrating", "hydration", "dry skin"],
    "cleanser": ["wash", "cleansing", "face wash"],
    "acne": ["breakout", "pimple", "oily skin"],
    "dark spot": ["pigmentation", "uneven tone", "brightening"],
    "sensitive": ["redness", "irritation"],
    "toner": ["pores", "pore"]
  };
  const terms = [query];
  for (const [k, vals] of Object.entries(aliases)) {
    if (query.includes(k) || vals.some(v => query.includes(v))) terms.push(k, ...vals);
  }
  for (const term of terms) {
    if (term && text.includes(term)) score += 5;
    for (const w of norm(term).split(" ").filter(x => x.length > 2)) if (text.includes(w)) score += 1;
  }
  return score;
}
function findProducts(q) {
  return PRODUCTS.map(p => ({p, s: scoreProduct(p,q)})).filter(x => x.s > 0).sort((a,b)=>b.s-a.s).map(x=>x.p);
}
function bySkinType(type) { return PRODUCTS.filter(p => p.skinTypes.includes(type)).slice(0,3); }
function byConcern(concern) {
  const map = {
    "acne": ["acne","breakouts","excess oil"],
    "dark spots": ["dark spots","uneven tone","dullness"],
    "dryness": ["dryness","tightness","flaking"],
    "excess oil": ["excess oil","visible pores"],
    "sensitivity": ["redness","sensitivity","dryness"],
    "fine lines": ["fine lines","dry under-eyes"]
  };
  const terms = map[concern] || [concern];
  return PRODUCTS.map(p => {
    const t = norm(productText(p));
    let s=0; for (const x of terms) if (t.includes(norm(x))) s+=5;
    return {p,s};
  }).filter(x=>x.s>0).sort((a,b)=>b.s-a.s).map(x=>x.p).slice(0,3);
}
function aiProductPrompt(p, q) {
  return `You are a skincare store sales assistant.

Customer message:
"${q}"

Product data:
${productBlock(p)}

Rules:
- Reply in natural, concise English.
- Use only the product data above.
- Do not invent products, prices, stock, URLs, ingredients, benefits, or claims.
- Do not make medical diagnosis or guaranteed treatment claims.
- If the customer describes a severe, painful, infected, persistent, or wounded skin condition, advise them to consult a qualified healthcare professional.
- Keep the answer under 7 short lines.
- Output only the customer-facing message.`;
}
function aiAdvicePrompt(label, products) {
  return `You are a skincare store sales assistant.

Customer need:
${label}

Available products:
${products.map((p,i)=>`Product ${i+1}:\n${productBlock(p)}`).join("\n")}

Rules:
- Reply in natural, concise English.
- Recommend at most 3 products from the list.
- Briefly explain why each may fit.
- Use only the data provided.
- Do not invent products, prices, stock, URLs, ingredients, benefits, or medical claims.
- For severe, painful, infected, persistent, or wounded conditions, advise consulting a qualified healthcare professional.
- Keep the answer under 10 short lines.
- Output only the customer-facing message.`;
}
function aiQuestionPrompt(p, q) {
  return `You are a skincare store sales assistant.

Product:
${productBlock(p)}

Customer question:
"${q}"

Rules:
- Answer only about this product.
- Use only the information above.
- Do not invent ingredients, benefits, prices, stock, URLs, or medical claims.
- Keep the answer under 7 short lines.
- Output only the customer-facing message.`;
}

if (!chatId) return response("", "Error: chatId was not received.", undefined, {}, callbackQueryId);

const s = savedSession || { step: "MAIN_MENU", temp: {}, hasStarted: false };
s.temp = s.temp || {};

function welcome() {
  return `Hi 👋
Welcome to the AI Skincare Sales Assistant demo.

You can:
• ask about products
• get recommendations based on skin type or concern
• create a test order
• track a test order

What would you like to do?`;
}

if (!s.hasStarted || ["/start","start","hello","hi","back_to_main"].includes(msg.toLowerCase())) {
  s.hasStarted = true; s.step = "MAIN_MENU"; s.temp = {};
  return response(chatId, welcome(), mainMenu(), s, callbackQueryId);
}

if (msg === "consulting") {
  s.step = "CONSULTING_MENU"; s.temp = {};
  return response(chatId, "Choose how you'd like to get product guidance:", consultingMenu(), s, callbackQueryId);
}
if (msg === "about_demo") {
  s.step = "MAIN_MENU"; s.temp = {};
  return response(chatId,
`About this demo

This is a proof-of-concept AI sales and customer-support assistant for skincare stores.

A production version can be connected to WooCommerce, product databases, Google Sheets, CRM systems, or other business tools.

Contact:
YOUR_CONTACT_INFO`, mainMenu(), s, callbackQueryId);
}
if (msg === "product_info") {
  s.step = "WAITING_PRODUCT_NAME";
  return response(chatId, "Tell me the product or need you're looking for.\n\nExamples:\nSunscreen for oily skin\nMoisturizer for dry skin\nAcne serum\nDark spots", backMenu(), s, callbackQueryId);
}
if (msg === "skin_type_advice") {
  s.step = "WAITING_SKIN_TYPE";
  return response(chatId, "Select your skin type:", skinTypesMenu(), s, callbackQueryId);
}
if (msg === "skin_problem_advice") {
  s.step = "WAITING_SKIN_PROBLEM";
  return response(chatId, "Select your main skin concern:", problemsMenu(), s, callbackQueryId);
}
if (msg === "start_order") {
  s.step = "WAITING_ORDER_PRODUCT"; s.temp = {};
  return response(chatId, "Type the product you'd like to order.\n\nExample: sunscreen, moisturizer, acne serum", orderBack(), s, callbackQueryId);
}
if (msg === "track_order") {
  s.step = "WAITING_ORDER_TRACKING"; s.temp = {};
  return response(chatId, "Send your test order code or phone number.\n\nFor a quick demo, try: SKN-1001", orderBack(), s, callbackQueryId);
}

if (s.step === "WAITING_PRODUCT_NAME") {
  const product = findProducts(msg)[0];
  if (!product) return response(chatId, `I couldn't find a matching demo product for "${msg}". Try sunscreen, moisturizer, cleanser, acne, dark spots, or toner.`, backMenu(), s, callbackQueryId);
  s.step = "CONSULTING_MENU"; s.temp.selectedProductId = product.id; s.temp.lastSuggestedProductId = product.id;
  return responseWithAI(chatId, aiProductPrompt(product,msg), productActions(product.id), s, callbackQueryId);
}

if (msg.startsWith("ask_")) {
  const p = findProductById(msg.replace("ask_",""));
  if (!p) return response(chatId,"Product not found.",consultingMenu(),s,callbackQueryId);
  s.step = "WAITING_PRODUCT_QUESTION"; s.temp.selectedProductId = p.id; s.temp.lastSuggestedProductId = p.id;
  return response(chatId, `Ask your question about "${p.name}".`, backMenu(), s, callbackQueryId);
}
if (s.step === "WAITING_PRODUCT_QUESTION") {
  const p = findProductById(s.temp.selectedProductId || s.temp.lastSuggestedProductId);
  if (!p) return response(chatId,"Please select the product again.",consultingMenu(),s,callbackQueryId);
  s.step = "CONSULTING_MENU";
  return responseWithAI(chatId, aiQuestionPrompt(p,msg), productActions(p.id), s, callbackQueryId);
}

const skinMap = { skin_oily:"oily", skin_dry:"dry", skin_combination:"combination", skin_sensitive:"sensitive" };
if (skinMap[msg]) {
  const type = skinMap[msg], products = bySkinType(type);
  s.step = "CONSULTING_MENU";
  if (products[0]) { s.temp.selectedProductId=products[0].id; s.temp.lastSuggestedProductId=products[0].id; }
  return responseWithAI(chatId, aiAdvicePrompt(`${type} skin`,products), backMenu(), s, callbackQueryId);
}
if (msg === "skin_unknown") {
  s.step = "WAITING_SKIN_DISCOVERY";
  return response(chatId, "Which description fits best?\n\n1. Gets oily or shiny quickly\n2. Often feels tight or dry\n3. Oily in some areas and dry in others\n4. Gets red or irritated easily", backMenu(), s, callbackQueryId);
}
if (s.step === "WAITING_SKIN_DISCOVERY") {
  const a = norm(msg);
  let type = a.startsWith("1") ? "oily" : a.startsWith("2") ? "dry" : a.startsWith("3") ? "combination" : a.startsWith("4") ? "sensitive" : null;
  if (!type) return response(chatId,"Please reply with 1, 2, 3, or 4.",backMenu(),s,callbackQueryId);
  const products = bySkinType(type);
  s.step = "CONSULTING_MENU";
  if (products[0]) { s.temp.selectedProductId=products[0].id; s.temp.lastSuggestedProductId=products[0].id; }
  return responseWithAI(chatId, aiAdvicePrompt(`${type} skin`,products), backMenu(), s, callbackQueryId);
}

const problemMap = {
  problem_acne:"acne",
  problem_spot:"dark spots",
  problem_dryness:"dryness",
  problem_oiliness:"excess oil",
  problem_sensitive:"sensitivity",
  problem_lines:"fine lines"
};
if (problemMap[msg]) {
  const concern = problemMap[msg], products = byConcern(concern);
  s.step = "CONSULTING_MENU";
  if (products[0]) { s.temp.selectedProductId=products[0].id; s.temp.lastSuggestedProductId=products[0].id; }
  if (!products.length) return response(chatId,"No matching demo product was found.",backMenu(),s,callbackQueryId);
  return responseWithAI(chatId, aiAdvicePrompt(concern,products), backMenu(), s, callbackQueryId);
}

if (msg.startsWith("order_")) {
  const p = findProductById(msg.replace("order_",""));
  if (!p) return response(chatId,"Product not found.",consultingMenu(),s,callbackQueryId);
  s.step = "WAITING_ORDER_NAME";
  s.temp = { selectedProductId:p.id, selectedProductName:p.name, lastSuggestedProductId:p.id };
  return response(chatId, `Test order for:\n${p.name}\n\nPlease enter your full name.`, orderBack(), s, callbackQueryId);
}

if (s.step === "WAITING_ORDER_PRODUCT") {
  const p = findProducts(msg)[0];
  if (!p) return response(chatId,"I couldn't find that demo product. Try sunscreen, moisturizer, cleanser, or serum.",orderBack(),s,callbackQueryId);
  s.step="WAITING_ORDER_NAME"; s.temp={selectedProductId:p.id,selectedProductName:p.name,lastSuggestedProductId:p.id};
  return response(chatId, `Selected:\n${p.name}\nPrice: ${p.price}\n\nPlease enter your full name.`, orderBack(), s, callbackQueryId);
}
if (s.step === "WAITING_ORDER_NAME") {
  if (msg.length < 2) return response(chatId,"Please enter a valid name.",orderBack(),s,callbackQueryId);
  s.temp.customerName=msg; s.step="WAITING_ORDER_PHONE";
  return response(chatId,"Please enter your phone number.",orderBack(),s,callbackQueryId);
}
if (s.step === "WAITING_ORDER_PHONE") {
  const phone = msg.replace(/\s+/g,"");
  if (!/^\+?[0-9]{8,15}$/.test(phone)) return response(chatId,"Please enter a valid phone number including country code when needed.",orderBack(),s,callbackQueryId);
  s.temp.customerPhone=phone; s.step="WAITING_ORDER_ADDRESS";
  return response(chatId,"Please enter a test delivery address.",orderBack(),s,callbackQueryId);
}
if (s.step === "WAITING_ORDER_ADDRESS") {
  if (msg.length < 5) return response(chatId,"Please enter a more complete address.",orderBack(),s,callbackQueryId);
  s.temp.customerAddress=msg; s.step="WAITING_ORDER_CONFIRMATION";
  return response(chatId,
`Please review your test order:

Product: ${s.temp.selectedProductName}
Name: ${s.temp.customerName}
Phone: ${s.temp.customerPhone}
Address: ${s.temp.customerAddress}`, orderConfirm(), s, callbackQueryId);
}
if (msg === "confirm_order") {
  if (!s.temp.selectedProductId || !s.temp.customerName || !s.temp.customerPhone || !s.temp.customerAddress) {
    s.step="MAIN_MENU"; s.temp={};
    return response(chatId,"Order information is incomplete. Please start again.",mainMenu(),s,callbackQueryId);
  }
  const code = orderCode();
  const order = {
    code, chatId,
    productId:s.temp.selectedProductId,
    productName:s.temp.selectedProductName,
    customerName:s.temp.customerName,
    customerPhone:s.temp.customerPhone,
    customerAddress:s.temp.customerAddress,
    status:"Received — awaiting review",
    createdAt:new Date().toISOString()
  };
  store.orders[code]=order;
  s.step="MAIN_MENU"; s.temp={};
  return response(chatId, `Your test order has been created ✅\n\nOrder code: ${code}\nProduct: ${order.productName}\nStatus: ${order.status}\n\nUse "Track order" from the main menu to test tracking.`, mainMenu(), s, callbackQueryId);
}
if (msg === "edit_order") {
  s.step="WAITING_ORDER_NAME";
  return response(chatId,"Let's update the details. Please enter your full name again.",orderBack(),s,callbackQueryId);
}
if (msg === "cancel_order") {
  s.step="MAIN_MENU"; s.temp={};
  return response(chatId,"The test order was cancelled.",mainMenu(),s,callbackQueryId);
}
if (s.step === "WAITING_ORDER_TRACKING") {
  const q = msg.replace(/\s+/g,"");
  let found = store.orders[q] || Object.values(store.orders).find(o => o.customerPhone === q);
  if (!found && q === "SKN-1001") {
    found = { code:"SKN-1001", productName:"Lightweight SPF 50 Sunscreen for Oily Skin", status:"Ready to ship" };
  }
  if (!found) return response(chatId,"No test order was found. Try SKN-1001.",orderBack(),s,callbackQueryId);
  s.step="MAIN_MENU"; s.temp={};
  return response(chatId, `Order status 📦\n\nOrder code: ${found.code}\nProduct: ${found.productName}\nStatus: ${found.status}\nEstimated delivery: 2–3 business days`, mainMenu(), s, callbackQueryId);
}

if (!["WAITING_ORDER_NAME","WAITING_ORDER_PHONE","WAITING_ORDER_ADDRESS","WAITING_ORDER_CONFIRMATION","WAITING_ORDER_TRACKING"].includes(s.step)) {
  const p = findProducts(msg)[0];
  if (p) {
    s.step="CONSULTING_MENU"; s.temp.selectedProductId=p.id; s.temp.lastSuggestedProductId=p.id;
    return responseWithAI(chatId, aiProductPrompt(p,msg), productActions(p.id), s, callbackQueryId);
  }
}

return response(chatId,
`I couldn't understand that message.

Try:
• sunscreen for oily skin
• moisturizer for dry skin
• acne serum

Or choose an option from the menu.`, mainMenu(), s, callbackQueryId);

const aiText =
  $json.text ||
  $json.output ||
  $json.response ||
  $json.result ||
  $json.message ||
  $json.data ||
  "";

const original = $('Code in JavaScript').first().json;

return [
  {
    json: {
      chatId: original.chatId,
      text: String(aiText || "متأسفم، الان نتونستم پاسخ مشاوره‌ای تولید کنم. لطفاً دوباره امتحان کن.").trim(),
      replyMarkup: original.replyMarkup,
      session: original.session,
      callbackQueryId: original.callbackQueryId,
      aiRaw: $json
    }
  }
];

const update = $json || {};
const raw = update.body || update.data || update;

const chatId =
  raw.chatId ||
  raw.chat_id ||
  raw.message?.chat?.id ||
  raw.callback_query?.message?.chat?.id ||
  raw.callbackQuery?.message?.chat?.id ||
  raw.message?.from?.id ||
  raw.callback_query?.from?.id ||
  raw.callbackQuery?.from?.id ||
